package com.profa.notification;import org.springframework.security.core.*;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController@RequestMapping("/api/v1/notifications")public class NotificationController{final NotificationRepository r;public NotificationController(NotificationRepository r){this.r=r;}@GetMapping public List<Notification> mine(Authentication a){UUID id=UUID.fromString(a.getName());return r.findAll().stream().filter(x->id.equals(x.getUserId())).toList();}@PatchMapping("/{id}/read")public Notification read(@PathVariable UUID id){Notification n=r.findById(id).orElseThrow();n.setRead(true);return r.save(n);}}